//! Generated by Codex. Invocation budgets shared by admission and Wasmtime.

use mudu::common::result::RS;
use mudu::error::ErrorCode;
use mudu::mudu_error;
use mudu_sys::sync::SMutex;
use mudu_sys::time::{Instant, instant_now};
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::time::Duration;

/// Server-owned procedure limits. Missing settings use finite defaults.
#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct InvocationLimits {
    /// Total linear-memory bytes across all memories in one invocation.
    pub memory_bytes: usize,
    /// Wasm instruction fuel, including component initialization.
    pub fuel: u64,
    /// Wall-clock execution budget, including transaction setup.
    pub timeout_ms: u64,
    /// Maximum encoded procedure or host-call input size.
    pub max_input_bytes: usize,
    /// Maximum encoded procedure or host-call output size.
    pub max_output_bytes: usize,
    /// Maximum host calls, including resource-opening calls.
    pub max_host_calls: u64,
    /// Maximum simultaneously open worker sessions and file handles.
    pub max_resources: usize,
    /// Maximum total table elements in one invocation.
    pub table_elements: usize,
    /// Process-wide maximum admitted procedure calls.
    pub max_concurrent: usize,
    /// Maximum admitted calls sharing an application name.
    pub max_concurrent_per_app: usize,
    /// Process-wide reserved guest linear-memory budget.
    pub total_memory_bytes: usize,
}

impl Default for InvocationLimits {
    fn default() -> Self {
        Self {
            memory_bytes: 128 * 1024 * 1024,
            fuel: 1_000_000_000,
            timeout_ms: 30_000,
            max_input_bytes: 8 * 1024 * 1024,
            max_output_bytes: 8 * 1024 * 1024,
            max_host_calls: 10_000,
            max_resources: 256,
            table_elements: 100_000,
            max_concurrent: 4,
            max_concurrent_per_app: 2,
            total_memory_bytes: 512 * 1024 * 1024,
        }
    }
}

impl InvocationLimits {
    /// Rejects disabled, overflowing, or inconsistent budgets.
    pub fn validate(&self) -> RS<()> {
        if self.memory_bytes == 0
            || self.fuel == 0
            || self.timeout_ms == 0
            || self.max_input_bytes == 0
            || self.max_output_bytes == 0
            || self.max_host_calls == 0
            || self.max_resources == 0
            || self.table_elements == 0
            || self.max_concurrent == 0
            || self.max_concurrent_per_app == 0
            || self.memory_bytes > self.total_memory_bytes
            || self.max_concurrent_per_app > self.max_concurrent
            || instant_now()
                .checked_add(Duration::from_millis(self.timeout_ms))
                .is_none()
        {
            return Err(mudu_error!(
                ErrorCode::InvalidArgument,
                "invalid procedure resource limits"
            ));
        }
        Ok(())
    }
}

/// Request-scoped cancellation and commit boundary, shared with host calls.
pub struct InvocationContext {
    pub(crate) resources: SMutex<super::invocation_resources::HostResources>,
    /// Effective server-owned limits for this invocation.
    pub limits: InvocationLimits,
    deadline: Instant,
    state: SMutex<State>,
    host_calls: AtomicU64,
    exceeded: AtomicBool,
    disconnected: AtomicBool,
}

#[derive(Default)]
struct State {
    cancelled: bool,
    committing: bool,
}

impl InvocationContext {
    /// Creates a fresh invocation budget before transaction setup.
    pub fn new(limits: InvocationLimits) -> RS<Arc<Self>> {
        limits.validate()?;
        let deadline = instant_now()
            .checked_add(Duration::from_millis(limits.timeout_ms))
            .ok_or_else(|| {
                mudu_error!(ErrorCode::InvalidArgument, "procedure deadline overflow")
            })?;
        Ok(Arc::new(Self {
            resources: super::invocation_resources::new_resources(),
            limits,
            deadline,
            state: SMutex::new(State::default()),
            host_calls: AtomicU64::new(0),
            exceeded: AtomicBool::new(false),
            disconnected: AtomicBool::new(false),
        }))
    }

    /// Requests cancellation unless the commit boundary has already been crossed.
    pub fn cancel(&self) {
        self.disconnected.store(true, Ordering::Release);
        if let Ok(mut state) = self.state.lock()
            && !state.committing
        {
            state.cancelled = true;
        }
    }

    pub(crate) fn is_cancelled(&self) -> bool {
        self.disconnected.load(Ordering::Acquire)
    }

    /// Checks cancellation, deadline and previously exhausted host budgets.
    pub fn check(&self) -> RS<()> {
        let state = self.state.lock()?;
        if self.exceeded.load(Ordering::Acquire) {
            return Err(mudu_error!(
                ErrorCode::OutOfMemory,
                "procedure resource budget exhausted"
            ));
        }
        if !state.committing && (state.cancelled || instant_now() >= self.deadline) {
            return Err(mudu_error!(
                ErrorCode::Interrupted,
                "procedure cancelled or deadline exceeded"
            ));
        }
        Ok(())
    }

    /// Atomically decides whether cancellation or transaction commit wins.
    pub fn begin_commit(&self) -> RS<()> {
        let mut state = self.state.lock()?;
        if state.cancelled
            || instant_now() >= self.deadline
            || self.exceeded.load(Ordering::Acquire)
        {
            return Err(mudu_error!(
                ErrorCode::Interrupted,
                "procedure stopped before commit"
            ));
        }
        state.committing = true;
        Ok(())
    }

    pub(crate) fn exhaust(&self) {
        self.exceeded.store(true, Ordering::Release);
    }

    /// Checks a host-call input and charges the call count before side effects.
    pub fn enter_host(&self, size: usize) -> wasmtime::Result<()> {
        self.check()?;
        if size > self.limits.max_input_bytes
            || self.host_calls.fetch_add(1, Ordering::AcqRel) >= self.limits.max_host_calls
        {
            self.exceeded.store(true, Ordering::Release);
            self.check()?;
        }
        Ok(())
    }

    /// Checks a host response after the operation completes, before guest reentry.
    pub fn leave_host(&self, bytes: Vec<u8>) -> wasmtime::Result<Vec<u8>> {
        if bytes.len() > self.limits.max_output_bytes {
            self.exceeded.store(true, Ordering::Release);
        }
        self.check()?;
        Ok(bytes)
    }
}

/// Cancels a managed invocation when its request future is dropped.
pub(crate) struct CancelOnDrop(pub Option<Arc<InvocationContext>>);
impl Drop for CancelOnDrop {
    fn drop(&mut self) {
        if let Some(control) = &self.0 {
            control.cancel();
        }
    }
}
